#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>
#include <vector>

namespace off {
constexpr uintptr_t viewMatrix = 0x0;
constexpr uintptr_t entityList = 0x0;
constexpr uintptr_t localPlayer = 0x0;
constexpr uintptr_t entityStride = 0x8;
constexpr int maxEntities = 64;
constexpr uintptr_t health = 0x0;
constexpr uintptr_t team = 0x0;
constexpr uintptr_t boneArray = 0x0;
constexpr uintptr_t boneStride = 0x30;
constexpr int headBone = 8;
}

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
struct Mat4 { float m[16]; };

struct Entity {
    uintptr_t addr;
    int health;
    int team;
    Vec3 head;
};

class Memory {
public:
    ~Memory() { if (handle_) CloseHandle(handle_); }

    bool attach(const wchar_t* exe, const wchar_t* module) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
            if (!_wcsicmp(pe.szExeFile, exe)) { pid_ = pe.th32ProcessID; break; }
        CloseHandle(snap);
        if (!pid_) return false;

        handle_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid_);
        if (!handle_) return false;

        snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
        if (snap == INVALID_HANDLE_VALUE) return false;
        MODULEENTRY32W me{};
        me.dwSize = sizeof(me);
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
            if (!_wcsicmp(me.szModule, module)) { base_ = reinterpret_cast<uintptr_t>(me.modBaseAddr); break; }
        CloseHandle(snap);
        return base_ != 0;
    }

    template <typename T>
    T read(uintptr_t addr) const {
        T v{};
        ReadProcessMemory(handle_, reinterpret_cast<LPCVOID>(addr), &v, sizeof(T), nullptr);
        return v;
    }

    DWORD pid() const { return pid_; }
    uintptr_t base() const { return base_; }

    Mat4 viewMatrix() const { return read<Mat4>(base_ + off::viewMatrix); }
    uintptr_t localPlayer() const { return read<uintptr_t>(base_ + off::localPlayer); }

    Vec3 bonePos(uintptr_t ent, int bone) const {
        uintptr_t bones = read<uintptr_t>(ent + off::boneArray);
        if (!bones) return {};
        uintptr_t b = bones + bone * off::boneStride;
        return { read<float>(b + 0x0C), read<float>(b + 0x1C), read<float>(b + 0x2C) };
    }

    std::vector<Entity> entities() const {
        std::vector<Entity> out;
        uintptr_t local = localPlayer();
        int localTeam = local ? read<int>(local + off::team) : -1;
        uintptr_t list = base_ + off::entityList;
        for (int i = 0; i < off::maxEntities; ++i) {
            uintptr_t e = read<uintptr_t>(list + i * off::entityStride);
            if (!e || e == local) continue;
            int hp = read<int>(e + off::health);
            if (hp <= 0) continue;
            int tm = read<int>(e + off::team);
            if (tm == localTeam) continue;
            out.push_back({ e, hp, tm, bonePos(e, off::headBone) });
        }
        return out;
    }

private:
    HANDLE handle_ = nullptr;
    DWORD pid_ = 0;
    uintptr_t base_ = 0;
};

#include "mem.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <thread>
#include <utility>

using Clock = std::chrono::steady_clock;

constexpr const wchar_t* kExe = L"linden.exe";
constexpr const wchar_t* kModule = L"linden.exe";
constexpr float kFovRadius = 240.f;
constexpr float kEaseMs = 180.f;
constexpr float kMinGain = 0.06f;
constexpr float kMaxGain = 0.35f;
constexpr float kCountsPerPixel = 1.0f;
constexpr int kAimKey = VK_RBUTTON;
constexpr int kExitKey = VK_END;

static BOOL CALLBACK findWindow(HWND hwnd, LPARAM lp) {
    auto* ctx = reinterpret_cast<std::pair<DWORD, HWND>*>(lp);
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    if (pid == ctx->first && IsWindowVisible(hwnd) && !GetWindow(hwnd, GW_OWNER)) {
        ctx->second = hwnd;
        return FALSE;
    }
    return TRUE;
}

static bool worldToScreen(const Vec3& p, const Mat4& vm, int w, int h, Vec2& out) {
    const float* m = vm.m;
    float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];
    if (cw < 0.01f) return false;
    float cx = m[0] * p.x + m[1] * p.y + m[2] * p.z + m[3];
    float cy = m[4] * p.x + m[5] * p.y + m[6] * p.z + m[7];
    out.x = (w * 0.5f) * (1.f + cx / cw);
    out.y = (h * 0.5f) * (1.f - cy / cw);
    return true;
}

static float easeOutCubic(float t) {
    float u = 1.f - t;
    return 1.f - u * u * u;
}

static void moveMouse(int dx, int dy) {
    INPUT in{};
    in.type = INPUT_MOUSE;
    in.mi.dx = dx;
    in.mi.dy = dy;
    in.mi.dwFlags = MOUSEEVENTF_MOVE;
    SendInput(1, &in, sizeof(in));
}

int main() {
    Memory mem;
    if (!mem.attach(kExe, kModule)) {
        std::puts("attach failed");
        return 1;
    }

    std::pair<DWORD, HWND> ctx{ mem.pid(), nullptr };
    EnumWindows(findWindow, reinterpret_cast<LPARAM>(&ctx));
    if (!ctx.second) {
        std::puts("window not found");
        return 1;
    }
    HWND hwnd = ctx.second;

    uintptr_t locked = 0;
    auto lockStart = Clock::now();
    float carryX = 0.f, carryY = 0.f;

    while (!(GetAsyncKeyState(kExitKey) & 0x8000)) {
        if (!(GetAsyncKeyState(kAimKey) & 0x8000) || GetForegroundWindow() != hwnd) {
            locked = 0;
            carryX = carryY = 0.f;
            std::this_thread::sleep_for(std::chrono::milliseconds(2));
            continue;
        }

        RECT rc;
        GetClientRect(hwnd, &rc);
        int w = rc.right - rc.left, h = rc.bottom - rc.top;
        float cx = w * 0.5f, cy = h * 0.5f;
        Mat4 vm = mem.viewMatrix();

        uintptr_t best = 0;
        Vec2 bestPos{};
        float bestDist = kFovRadius;
        for (const Entity& e : mem.entities()) {
            Vec2 s;
            if (!worldToScreen(e.head, vm, w, h, s)) continue;
            float d = std::hypot(s.x - cx, s.y - cy);
            if (d < bestDist) { bestDist = d; best = e.addr; bestPos = s; }
        }

        if (!best) {
            locked = 0;
            std::this_thread::sleep_for(std::chrono::milliseconds(2));
            continue;
        }
        if (best != locked) {
            locked = best;
            lockStart = Clock::now();
            carryX = carryY = 0.f;
        }

        float ms = std::chrono::duration<float, std::milli>(Clock::now() - lockStart).count();
        float gain = kMinGain + (kMaxGain - kMinGain) * easeOutCubic(std::min(ms / kEaseMs, 1.f));
        float dx = (bestPos.x - cx) * gain * kCountsPerPixel + carryX;
        float dy = (bestPos.y - cy) * gain * kCountsPerPixel + carryY;
        int mx = static_cast<int>(dx), my = static_cast<int>(dy);
        carryX = dx - mx;
        carryY = dy - my;
        if (mx || my) moveMouse(mx, my);

        std::this_thread::sleep_for(std::chrono::milliseconds(4));
    }
    return 0;
}
